1	package netdiag
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/netip"
8		"slices"
9		"strings"
10		"testing"
11		"time"
12	
13		"github.com/anthnel/devdesk/internal/docker"
14		"github.com/anthnel/devdesk/internal/netiface"
15		"github.com/anthnel/devdesk/internal/ui/testutil"
16	)
17	
18	// DEVDESK-331 step 4: the bridge row wired into the producer. The network
19	// reads are always fakes; nothing here reaches a real engine or interface.
20	
21	const (
22		testNetID    = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
23		testNetName  = "app_net"
24		testGateway  = "172.18.0.1"
25		bridgeTimout = 2 * time.Second
26	)
27	
28	// netCtr is a running container on one network, whose endpoint carries id.
29	func netCtr(mode, id string) docker.ContainerNetworking {
30		return docker.ContainerNetworking{
31			Name: "web-1", Running: true, Mode: mode,
32			Networks: []docker.EndpointNetwork{{
33				Name: testNetName, NetworkID: id,
34				IPv4:    netip.MustParseAddr("172.18.0.5"),
35				Gateway: netip.MustParseAddr(testGateway),
36			}},
37		}
38	}
39	
40	// ifaceWith is an interface carrying one IPv4 CIDR.
41	func ifaceWith(name, cidr string) netiface.Interface {
42		return netiface.Interface{Name: name, State: "UP", IPv4: []string{cidr}}
43	}
44	
45	// bridgeFake answers the network read with name and offers ifaces.
46	func bridgeFake(name string, ifaces ...netiface.Interface) *fakeEngine {
47		return &fakeEngine{
48			traceFn:    oneHopTrace,
49			inspectNet: netCtr("app_net", testNetID),
50			networkVal: docker.NetworkBridge{Driver: "bridge", Name: name},
51			ifacesVal:  ifaces,
52		}
53	}
54	
55	// bridgeRun launches a trace of 1.1.1.1 from the web-1 source and feeds every
56	// message of the producer to the model.
57	func bridgeRun(t *testing.T, f *fakeEngine) *PathModel {
58		t.Helper()
59		captureLog(t)
60		pm := pmWith(t, f)
61		pm.source = webSource
62		pm, cmd := launched(t, pm, "1.1.1.1")
63		for _, msg := range testutil.Msgs(cmd) {
64			pm, _ = pmFeed(t, pm, msg)
65		}
66		for msg := range pm.msgs {
67			pm, _ = pmFeed(t, pm, msg)
68		}
69		return pm
70	}
71	
72	func bridgeRows(pm *PathModel) []string {
73		var out []string
74		for _, s := range pm.table.Items() {
75			if s.Kind == stepBridge {
76				out = append(out, s.addressCell())
77			}
78		}
79		return out
80	}
81	
82	func requireBridge(t *testing.T, pm *PathModel, want string) {
83		t.Helper()
84		got := bridgeRows(pm)
85		if want == "" {
86			if len(got) != 0 {
87				t.Fatalf("bridge rows = %v, want none (rows %v)", got, rowKinds(pm))
88			}
89			return
90		}
91		if !slices.Equal(got, []string{want}) {
92			t.Fatalf("bridge rows = %v, want [%s] (rows %v)", got, want, rowKinds(pm))
93		}
94	}
95	
96	// Criterion 1: the default network and the host's docker0 give a bridge line,
97	// and so does a user-defined br-... network.
98	func TestPathBridgeRowShownWhenTheHostInterfaceCarriesTheGateway(t *testing.T) {
99		for _, name := range []string{"docker0", "br-3f2a1b4c5d6e"} {
100			t.Run(name, func(t *testing.T) {
101				f := bridgeFake(name, ifaceWith("lo", "127.0.0.1/8"), ifaceWith(name, testGateway+"/16"))
102				pm := bridgeRun(t, f)
103	
104				requireBridge(t, pm, name)
105				kinds := rowKinds(pm)
106				if want := []string{"container", "network", "bridge", "source"}; !slices.Equal(kinds[:4], want) {
107					t.Fatalf("rows = %v, want %v first", kinds, want)
108				}
109				if f.networkCalls != 1 || f.ifacesCalls != 1 {
110					t.Fatalf("network calls %d, interfaces calls %d, want 1 and 1", f.networkCalls, f.ifacesCalls)
111				}
112			})
113		}
114	}
115	
116	// Criterion 2: no interface of that name carries the gateway, so no row, and
117	// the hops still show.
118	func TestPathBridgeRowAbsentWhenNoInterfaceMatches(t *testing.T) {
119		f := bridgeFake("docker0", ifaceWith("eth0", "192.168.1.21/24"), ifaceWith("docker0", "10.9.0.1/16"))
120		pm := bridgeRun(t, f)
121	
122		requireBridge(t, pm, "")
123		if got := pmHopTTLs(pm); !slices.Equal(got, []int{1}) {
124			t.Fatalf("hops = %v, want [1]: the trace must go on", got)
125		}
126		if pm.state != pathDone {
127			t.Fatalf("state = %v, want pathDone", pm.state)
128		}
129	}
130	
131	// Criterion 3: same container, same engine answer; only this machine's
132	// interface list differs. The engine is never asked anything else for it.
133	func TestPathBridgeFollowsThisMachinesInterfaces(t *testing.T) {
134		with := bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
135		without := bridgeFake("docker0", ifaceWith("eth0", "192.168.1.21/24"))
136	
137		pmWithIf, pmWithout := bridgeRun(t, with), bridgeRun(t, without)
138	
139		requireBridge(t, pmWithIf, "docker0")
140		requireBridge(t, pmWithout, "")
141		for name, f := range map[string]*fakeEngine{"with": with, "without": without} {
142			if f.osCalls != 0 {
143				t.Errorf("%s: engineOS called %d times for the bridge, want 0", name, f.osCalls)
144			}
145		}
146	}
147	
148	func TestReadPathBridgeReadsNothingWhenThereIsNoBridgeToFind(t *testing.T) {
149		stopped := netCtr("app_net", testNetID)
150		stopped.Running = false
151		ambiguous := netCtr("app_net", testNetID)
152		ambiguous.Networks = append(ambiguous.Networks, docker.EndpointNetwork{
153			Name: "b_net", NetworkID: testNetID, Gateway: netip.MustParseAddr("172.19.0.1"),
154		})
155		tests := []struct {
156			name string
157			ctr  docker.ContainerNetworking
158		}{
159			{"stopped", stopped},
160			{"host mode", netCtr("host", testNetID)},
161			{"none mode", netCtr("none", testNetID)},
162			{"shared namespace", netCtr("container:abc", testNetID)},
163			{"undetermined (network equality)", ambiguous},
164			{"empty network id", netCtr("app_net", "")},
165			{"zero value", docker.ContainerNetworking{}},
166		}
167		for _, tc := range tests {
168			t.Run(tc.name, func(t *testing.T) {
169				f := bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
170				if got := readPathBridge(context.Background(), tc.ctr, bridgeTimout, f.engine()); got != "" {
171					t.Fatalf("bridge = %q, want empty", got)
172				}
173				if f.networkCalls != 0 || f.ifacesCalls != 0 {
174					t.Fatalf("network calls %d, interfaces calls %d, want 0 and 0", f.networkCalls, f.ifacesCalls)
175				}
176			})
177		}
178	}
179	
180	// The same cases through the producer, in a model: no call, no row.
181	func TestPathBridgeNoReadForHostNoneSharedStopped(t *testing.T) {
182		for _, mode := range []string{"host", "none", "container:abc"} {
183			t.Run(mode, func(t *testing.T) {
184				f := bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
185				f.inspectNet = netCtr(mode, testNetID)
186				pm := bridgeRun(t, f)
187				requireBridge(t, pm, "")
188				if f.networkCalls != 0 || f.ifacesCalls != 0 {
189					t.Fatalf("network calls %d, interfaces calls %d, want 0 and 0", f.networkCalls, f.ifacesCalls)
190				}
191			})
192		}
193		t.Run("stopped", func(t *testing.T) {
194			f := bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
195			f.inspectNet.Running = false
196			pm := bridgeRun(t, f)
197			requireBridge(t, pm, "")
198			if f.networkCalls != 0 || f.ifacesCalls != 0 {
199				t.Fatalf("network calls %d, interfaces calls %d, want 0 and 0", f.networkCalls, f.ifacesCalls)
200			}
201		})
202	}
203	
204	func TestPathBridgeNotReadFromThisMachine(t *testing.T) {
205		f := bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
206		captureLog(t)
207		pm := pmWith(t, f)
208		pm, cmd := launched(t, pm, "1.1.1.1")
209		for _, msg := range testutil.Msgs(cmd) {
210			pm, _ = pmFeed(t, pm, msg)
211		}
212		requireBridge(t, pm, "")
213		if f.networkCalls != 0 || f.ifacesCalls != 0 || f.inspectCalls != 0 {
214			t.Fatalf("network %d, interfaces %d, inspect %d calls from this machine, want none", f.networkCalls, f.ifacesCalls, f.inspectCalls)
215		}
216	}
217	
218	// A macvlan or any other driver without a bridge of its own answers Name "":
219	// no row, and the interfaces are not even listed.
220	func TestPathBridgeEmptyNameShowsNoRow(t *testing.T) {
221		f := bridgeFake("", ifaceWith("docker0", testGateway+"/16"))
222		f.networkVal.Driver = "macvlan"
223		pm := bridgeRun(t, f)
224	
225		requireBridge(t, pm, "")
226		if f.networkCalls != 1 {
227			t.Fatalf("network calls = %d, want 1", f.networkCalls)
228		}
229		if f.ifacesCalls != 0 {
230			t.Fatalf("interfaces listed %d times for an empty name, want 0", f.ifacesCalls)
231		}
232	}
233	
234	// A failed read shows nothing, is logged raw with the package prefix, and the
235	// trace runs to its end.
236	func TestPathBridgeReadFailureIsLoggedNotShown(t *testing.T) {
237		tests := []struct {
238			name string
239			fake func() *fakeEngine
240			raw  string
241		}{
242			{"network read fails", func() *fakeEngine {
243				f := bridgeFake("docker0", ifaceWith("docker0", testGateway+"/16"))
244				f.networkErr = errors.New("net-boom-raw")
245				return f
246			}, "net-boom-raw"},
247			{"interface list fails", func() *fakeEngine {
248				f := bridgeFake("docker0")
249				f.ifacesErr = errors.New("if-boom-raw")
250				return f
251			}, "if-boom-raw"},
252		}
253		for _, tc := range tests {
254			t.Run(tc.name, func(t *testing.T) {
255				f := tc.fake()
256				logs := captureLog(t)
257				pm := pmWith(t, f)
258				pm.source = webSource
259				pm, cmd := launched(t, pm, "1.1.1.1")
260				for _, msg := range testutil.Msgs(cmd) {
261					pm, _ = pmFeed(t, pm, msg)
262				}
263				for msg := range pm.msgs {
264					pm, _ = pmFeed(t, pm, msg)
265				}
266	
