345	// The gateway used is the one of the default-route endpoint, not of another.
346	func TestReadPathBridgeUsesTheDefaultRouteEndpoint(t *testing.T) {
347		n := docker.ContainerNetworking{Name: "web-1", Running: true, Mode: "a_net", Networks: []docker.EndpointNetwork{
