1	package netdiag
2	
3	import (
4		"net/netip"
5	
6		"github.com/anthnel/devdesk/internal/netiface"
7	)
8	
9	// hostBridge returns the name of this machine's interface called exactly want
10	// (case sensitive) that carries gw among its IPv4 addresses, or "" when there
11	// is none. Malformed CIDR entries are ignored.
12	func hostBridge(want string, gw netip.Addr, ifaces []netiface.Interface) string {
13		if want == "" || !gw.IsValid() {
14			return ""
15		}
16		for _, ifc := range ifaces {
17			if ifc.Name != want {
18				continue
19			}
20			for _, cidr := range ifc.IPv4 {
21				if p, err := netip.ParsePrefix(cidr); err == nil && p.Addr() == gw {
22					return ifc.Name
23				}
24			}
25		}
26		return ""
27	}
28

1	package netdiag
2	
3	import (
4		"fmt"
5		"net/netip"
6		"strings"
7	
8		"github.com/anthnel/devdesk/internal/docker"
9	)
10	
11	// containerAttach says how a container is attached to a network.
12	type containerAttach int
13	
14	// The ways a container can be attached.
15	const (
16		attachNetwork containerAttach = iota
17		attachHost
18		attachNone
19		attachShared
20		attachUndetermined
21	)
22	
23	// pathContainer is what the column says about the container a trace starts in.
24	type pathContainer struct {
25		Name     string // display-safe
26		Known    bool   // false: the inspection failed
27		Running  bool
28		Attach   containerAttach
29		Network  string     // attachNetwork only, display-safe
30		Networks int        // number of endpoints, for "undetermined (N networks)"
31		Addr     netip.Addr // the container's IPv4 on Network
32		Gateway  netip.Addr // Network's gateway
33		Bridge   string     // attachNetwork only: the host interface read for Network; "" when none
34	}
35	
36	// withBridge returns a copy of c carrying the bridge interface name. The name
37	// is kept only for a container attached to a network, and only when not empty.
38	func (c pathContainer) withBridge(name string) pathContainer {
39		if c.Attach == attachNetwork && name != "" {
40			c.Bridge = name
41		}
42		return c
43	}
44	
45	const (
46		modeHost            = "host"
47		modeNone            = "none"
48		modeSharedPrefix    = "container:"
49		textUndetermined    = "undetermined"
50		textHostNetwork     = "host (shares this machine's stack)"
51		textNoNetwork       = "none (no network)"
52		textSharedNetwork   = "shares another container's network"
53		textNotRunning      = "not running"
54		textTraceFromHost   = "from this machine, not from the container"
55		textTraceSharedHost = "from this machine (shared with the container)"
56	)
57	
58	// newPathContainer converts an inspection into a pathContainer. Every text the
59	// engine returned is sanitized here, so the cells are display-safe.
60	func newPathContainer(src pathSource, n docker.ContainerNetworking, err error) pathContainer {
61		c := pathContainer{Name: src.Name, Attach: attachUndetermined}
62		if err != nil {
63			return c
64		}
65		c.Known = true
66		if name := engineText(n.Name); name != "" {
67			c.Name = name
68		}
69		c.Running = n.Running
70		if !n.Running {
71			return c
72		}
73		switch {
74		case n.Mode == modeHost:
75			c.Attach = attachHost
76		case n.Mode == modeNone:
77			c.Attach = attachNone
78		case strings.HasPrefix(n.Mode, modeSharedPrefix):
79			c.Attach = attachShared
80		default:
81			c.Networks = len(n.Networks)
82			if picked, ok := defaultRouteNetwork(n.Networks); ok {
83				c.Attach = attachNetwork
84				c.Network = engineText(picked.Name)
85				c.Addr = picked.IPv4
86				c.Gateway = picked.Gateway
87			}
88		}
89		return c
90	}
91	
92	// defaultRouteNetwork picks the network that holds the container's default
93	// route: among the endpoints with a gateway, the one with the strictly highest
94	// gateway priority. A tie, or a priority missing among several candidates, is
95	// never guessed. The input is not modified.
96	func defaultRouteNetwork(nets []docker.EndpointNetwork) (docker.EndpointNetwork, bool) {
97		var candidates []docker.EndpointNetwork
98		for _, e := range nets {
99			if e.Gateway.IsValid() {
100				candidates = append(candidates, e)
101			}
102		}
103		switch len(candidates) {
104		case 0:
105			return docker.EndpointNetwork{}, false
106		case 1:
107			return candidates[0], true
108		}
109		best := -1
110		for i, e := range candidates {
111			if e.GwPriority == nil {
112				return docker.EndpointNetwork{}, false
113			}
114			if best < 0 || *e.GwPriority > *candidates[best].GwPriority {
115				best = i
116			}
117		}
118		for i, e := range candidates {
119			if i != best && *e.GwPriority == *candidates[best].GwPriority {
120				return docker.EndpointNetwork{}, false
121			}
122		}
123		return candidates[best], true
124	}
125	
126	// containerText is the Address cell of the container row.
127	func (c pathContainer) containerText() string {
128		switch {
129		case c.Known && !c.Running:
130			return c.Name + " (" + textNotRunning + ")"
131		case c.Attach == attachNetwork && c.Addr.IsValid():
132			return c.Name + " (" + c.Addr.String() + ")"
133		}
134		return c.Name
135	}
136	
137	// networkText is the Address cell of the network row.
138	func (c pathContainer) networkText() string {
139		switch c.Attach {
140		case attachNetwork:
141			if c.Gateway.IsValid() {
142				return c.Network + " via " + c.Gateway.String()
143			}
144			return c.Network
145		case attachHost:
146			return textHostNetwork
147		case attachNone:
148			return textNoNetwork
149		case attachShared:
150			return textSharedNetwork
151		}
152		if c.Networks > 1 {
153			return fmt.Sprintf("%s (%d networks)", textUndetermined, c.Networks)
154		}
155		return textUndetermined
156	}
157	
158	// traceText is the Address cell of the trace row.
159	func (c pathContainer) traceText() string {
160		if c.Attach == attachHost {
161			return textTraceSharedHost
162		}
163		return textTraceFromHost
164	}
165	
166	// dimNetwork reports whether the network row says nothing about a path.
167	func (c pathContainer) dimNetwork() bool {
168		return c.Attach == attachUndetermined || c.Attach == attachNone
169	}
170

