19	// pathChanCap holds a whole trace: every hop (at most MaxHopsLimit), the
20	// resolved message and the done message. The producer therefore never waits
21	// for a reader. Contract: resolved now carries source and ctr but is still one
22	// message, so 1 resolved + MaxHopsLimit (30) hops + 1 done = 32 = pathChanCap,
23	// and sendDone never evicts resolved with the real engine.
24	const pathChanCap = nettrace.MaxHopsLimit + 2
